/* Local workspace. The saved reader is a separate, sandboxed document. */
'use strict';
const $ = (id) => document.getElementById(id);
const token = document.querySelector('meta[name="distill-token"]').content;
const state = {view:'new', input:'youtube', output:'page', look:'forest', recording:'meeting', jobs:[], library:[], selectedJob:null, settings:null, busy:false, noticeTimer:null,generationInfo:{}};
const labels = {queued:'Queued',retrieving:'Retrieving captions',awaiting_approval:'Needs approval',transcribing:'Transcribing audio',analyzing:'Analyzing ideas',selecting_visuals:'Choosing visuals',validating:'Checking evidence',rendering:'Saving page',complete:'Ready',waiting_for_quota:'Waiting to retry',failed:'Stopped',cancelled:'Cancelled'};
const terminal = new Set(['complete','failed','cancelled']);
const active = new Set(['queued','retrieving','transcribing','analyzing','selecting_visuals','validating','rendering','waiting_for_quota']);
const escapeHTML = (value) => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const date = (value) => new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const stageBadge = (job) => `<span class="badge ${job.state === 'failed' ? 'error' : ['awaiting_approval','waiting_for_quota'].includes(job.state) ? 'warning' : job.state === 'complete' ? 'ok' : active.has(job.state) ? 'live' : ''}">${escapeHTML(labels[job.state] || job.state)}</span>`;
// Icons come from the sprite in index.html. Covers give each source its own patch of the terrain in one of six tints,
// chosen from its id; the CSP blocks style attributes in markup, so the offsets are set through the CSSOM.
const icon = (name) => `<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
function seed(text){let hash=2166136261;for(const char of String(text))hash=Math.imul(hash^char.charCodeAt(0),16777619);return hash>>>0;}
const coverTint = (id) => `cover t${seed(id)%6}`;
function paintCovers(root){root.querySelectorAll('[data-seed]').forEach(item=>{const hash=seed(item.dataset.seed);item.style.setProperty('--mx',`${hash%100}%`);item.style.setProperty('--my',`${(hash>>>7)%100}%`);item.style.setProperty('--gx',`${20+(hash>>>14)%60}%`);item.style.setProperty('--gy',`${(hash>>>20)%50}%`);});}

async function api(path, options={}) {
  const headers = {'x-distill':token, ...options.headers};
  if (options.body && !(options.body instanceof FormData)) headers['Content-Type']='application/json';
  const response=await fetch(path,{...options,headers});
  if(!response.ok){let message='The request could not finish. Try again.';try{const body=await response.json();message=typeof body.detail==='string'?body.detail:message;}catch{}throw new Error(message);}
  return response;
}
async function json(path,options){return(await api(path,options)).json();}
function notice(message,error=false){clearTimeout(state.noticeTimer);$('notice').textContent=message;$('notice').classList.toggle('error',error);$('notice').hidden=false;state.noticeTimer=setTimeout(()=>$('notice').hidden=true,12000);}
function formError(message){$('new-error').textContent=message;$('new-error').hidden=!message;if(!message)$('video-url').removeAttribute('aria-invalid');}
// Settings has sub-routes: #settings/looks shows that section's card alone, #settings/looks/forest opens that look's editor (looks.js).
function setView(route,updateHash=true){const [name,part,look]=String(route||'').split('/');const view=['library','new','jobs','reader','settings'].includes(name)?name:'new';const editing=view==='settings'&&part==='looks'&&Boolean(look);if(!editing&&typeof leaveLook==='function'&&!leaveLook())return;if(view!=='reader'&&!leaveEdit())return;state.view=view;document.querySelectorAll('.view').forEach(item=>item.hidden=item.id!==`view-${editing?'look':view}`);document.querySelectorAll('[data-view].nav-item').forEach(item=>{const on=item.dataset.view===view;item.classList.toggle('active',on);if(on)item.setAttribute('aria-current','page');else item.removeAttribute('aria-current');});if(updateHash)history.replaceState(null,'',`#${editing?`settings/looks/${look}`:view==='settings'&&part?`settings/${part}`:view}`);if(view==='library')loadLibrary().catch(error=>notice(error.message,true));if(view==='new')loadRecent();if(view==='jobs')refreshJobs().catch(error=>notice(error.message,true));if(view==='settings'&&!editing)showSection(part);scrollTo({top:0});if(view==='new'&&state.input==='youtube')$('video-url').focus({preventScroll:true});if(editing&&typeof openLookEditor==='function')openLookEditor(look);}
function inputMode(mode){state.input=mode;renderLobe();$('new-form').classList.toggle('is-import',mode!=='youtube');document.querySelectorAll('[data-input]').forEach(item=>{item.classList.toggle('active',item.dataset.input===mode);item.setAttribute('aria-pressed',String(item.dataset.input===mode));});$('youtube-fields').hidden=mode!=='youtube';$('import-fields').hidden=mode==='youtube';$('import-url-row').hidden=mode==='audio';$('recording-row').hidden=mode!=='audio';$('video-url').required=mode==='youtube';$('source-file').required=mode!=='youtube';$('source-file').accept=mode==='audio'?'.wav,.mp3,.m4a,.webm,.ogg,.opus,.flac,.mp4':'.txt,.srt,.vtt,.json';importHelp();$('existing-result').hidden=true;formError('');}
const transcriptionName=provider=>({soniox:'Soniox',groq:'Groq',local:'Local Whisper'})[provider]||'Soniox';
const workflowNames={video:'YouTube video',meeting:'Meeting recording',lecture:'Lecture or talk'};
function pressed(name,value){document.querySelectorAll(`[data-${name}]`).forEach(item=>{const on=item.dataset[name]===value;item.classList.toggle('active',on);item.setAttribute('aria-pressed',String(on));});}
function createLabel(){$('create-button').innerHTML=`${state.output==='lecture'?'Create lecture slides':'Create interactive page'}${icon('arrow-right')}`;}
function outputMode(format){state.output=format==='lecture'?'lecture':'page';pressed('output',state.output);$('look-row').hidden=state.output!=='lecture';renderLobe();if(!state.busy)createLabel();renderDefaults();}
// The tab under the start sheet: the stops this source and format will pass, drawn as a route like a job's.
function renderLobe(){const stops=[...(state.input==='audio'?['Audio','Transcript']:[state.input==='youtube'?'Captions':'Transcript']),'Ideas',...(state.output==='lecture'?['Slide plan','Deck']:['Page'])];const last=stops.length-1;const xs=stops.map((_,index)=>index*60+30),ys=stops.map((_,index)=>index===last?22:index%2?12:32);$('lobe').dataset.stops=stops.length;$('lobe-route').setAttribute('viewBox',`0 0 ${stops.length*60} 44`);$('lobe-route').innerHTML=`<path class="route-line" d="M${xs[0]} ${ys[0]}${xs.slice(1).map((x,index)=>{const mid=(xs[index]+x)/2;return`C${mid} ${ys[index]} ${mid} ${ys[index+1]} ${x} ${ys[index+1]}`;}).join('')}"/>`+xs.map((x,index)=>`<circle class="${index===last?'route-end':'route-stop'}" cx="${x}" cy="${ys[index]}" r="${index===last?6:4}"/>`).join('');$('lobe-stops').innerHTML=stops.map(stop=>`<span>${stop}</span>`).join('');$('lobe-count').textContent=`${stops.length} stops`;$('lobe-note').textContent=state.input==='audio'?'Asks before transcribing':'Saved as it goes';$('lobe').setAttribute('aria-label',`How it works: ${stops.join(', ')}`);}
function recordingMode(kind){state.recording=kind;pressed('recording',kind);importHelp();}
function importHelp(){const service=state.settings?.preferences.transcription_providers?.[state.recording];$('import-help').textContent=state.input==='audio'?(service==='local'?'Audio up to 1 GB. After you approve, Local Whisper transcribes it on this computer; nothing is uploaded.':`Audio up to 1 GB. The file stays local until you approve sending it to ${transcriptionName(service)}.`):'TXT, SRT, VTT, or transcript JSON up to 20 MB. Plain text has no verified timestamps.';}
// The server lists the deck looks with each one's light colours and title type, so a swatch is a small slide in that look.
const lookName=id=>(state.settings?.looks||[]).find(look=>look.id===id)?.name||'Forest green';
const lookSwatch='<span class="look-preview" aria-hidden="true"><b>Aa</b><i class="eyebrow"></i><i class="feature"><i></i></i><span class="bars"><i></i><i></i><i></i><i></i><i></i></span></span>';
function paintSwatches(container,looks){container.querySelectorAll('.look-preview').forEach((preview,index)=>Object.entries(looks[index].tokens).forEach(([key,value])=>preview.style.setProperty('--look-'+key,value)));}
function renderLooks(looks){$('look-options').innerHTML=looks.map(look=>`<button type="button" data-look="${escapeHTML(look.id)}" class="look-option" aria-pressed="false" aria-labelledby="look-name-${escapeHTML(look.id)}" aria-describedby="look-hint-${escapeHTML(look.id)}">${lookSwatch}<span id="look-name-${escapeHTML(look.id)}" class="look-name">${escapeHTML(look.name)}</span><span id="look-hint-${escapeHTML(look.id)}" class="look-hint">${escapeHTML(look.hint)}</span></button>`).join('');paintSwatches($('look-options'),looks);pressed('look',state.look);
  const chosen=radioValue('settings-look');$('settings-look-grid').innerHTML=looks.map(look=>`<div class="look-card"><label class="look-pick plain"><input type="radio" name="settings-look" value="${escapeHTML(look.id)}" form="settings-form">${lookSwatch}<span class="look-name">${escapeHTML(look.name)}</span><span class="look-hint">${escapeHTML(look.hint)}</span></label><div class="look-card-foot"><span class="look-tags"><span class="look-default">Default</span>${look.custom?'<span class="badge">Customized</span>':''}</span><a class="look-customize" href="#settings/looks/${escapeHTML(look.id)}">Customize<span class="sr-only"> ${escapeHTML(look.name)}</span>${icon('arrow-right')}</a></div></div>`).join('');paintSwatches($('settings-look-grid'),looks);if(chosen)checkRadio('settings-look',chosen);}
const radioValue=name=>document.querySelector(`input[name="${name}"]:checked`)?.value;
function checkRadio(name,value){document.querySelectorAll(`input[name="${name}"]`).forEach(input=>input.checked=input.value===value);}
function lookMode(look){state.look=(state.settings?.looks||[]).some(item=>item.id===look)?look:'forest';pressed('look',state.look);renderDefaults();}
function pagePreferences(){return{output_format:state.output,...(state.output==='lecture'?{slide_theme:state.look}:{}),language:$('new-language').value,knowledge_level:$('new-level').value,learning_goal:$('learning-goal').value.trim(),source_language:$('source-language').value.trim(),provider:$('new-provider').value};}
function renderDefaults(){if(!state.settings)return;const selected=pagePreferences();const defaults=state.settings.preferences;const usingDefaults=Object.entries(selected).every(([key,value])=>value===(defaults[key]||''));$('defaults-label').textContent=usingDefaults?'Using your saved defaults':'Using options for this page';document.querySelectorAll('.make-default').forEach(tag=>{tag.hidden=tag.closest('[data-output]').dataset.output!==(defaults.output_format||'page');});const values=[['Language',selected.language==='vi'?'Vietnamese':'English'],['Level',selected.knowledge_level.charAt(0).toUpperCase()+selected.knowledge_level.slice(1)],['AI',providerName(selected.provider)]];if(selected.slide_theme)values.push(['Look',lookName(selected.slide_theme)+' slides']);if(selected.learning_goal)values.push(['Goal','Learning goal set']);if(selected.source_language)values.push(['Captions',selected.source_language]);$('defaults-summary').innerHTML=values.map(([label,value])=>`<span class="chip"><small>${label}</small>${escapeHTML(value)}</span>`).join('');}
function paidRow(){const paid=!SUBSCRIPTION_PROVIDERS.includes($('new-provider').value);$('new-paid-row').hidden=!paid||Boolean(state.settings?.preferences.allow_paid_llm);if($('new-paid-row').hidden)$('new-paid').checked=false;renderDefaults();}
function applyDefaults(preferences){lookMode(preferences.slide_theme);outputMode(preferences.output_format);$('new-language').value=preferences.language;$('new-level').value=preferences.knowledge_level;$('new-provider').value=preferences.provider;$('learning-goal').value=preferences.learning_goal||'';$('source-language').value=preferences.source_language||'';paidRow();$('create-button').disabled=state.busy;}
async function loadSettings(apply=true){const result=await json('/api/settings');state.settings=result;const prefs=result.preferences;renderLooks(result.looks);renderConnections(prefs,result.credentials);if(apply)applyDefaults(prefs);$('settings-language').value=prefs.language;$('settings-level').value=prefs.knowledge_level;$('settings-provider').value=prefs.provider;$('codex-model').value=prefs.codex_model||'';$('deepseek-model').value=prefs.deepseek_model||'';checkRadio('settings-output',prefs.output_format||'page');checkRadio('settings-look',prefs.slide_theme||'forest');document.querySelectorAll('[data-workflow]').forEach(select=>select.value=prefs.transcription_providers?.[select.dataset.workflow]||'soniox');$('groq-model').value=prefs.groq_model;$('local-whisper-model').value=prefs.local_whisper_model||'large-v3-turbo';$('local-whisper-status').textContent=state.settings.tools['local-whisper']?'Local Whisper is installed on this computer.':'Local Whisper is not installed. Run "reelcrew transcribe setup whisper", or "pip install faster-whisper" in the app\'s Python, then reload Settings.';$('groq-free').checked=prefs.groq_free_only;importHelp();$('allow-paid').checked=prefs.allow_paid_llm;$('retain-audio').checked=prefs.retain_audio;['codex','claude'].forEach(tool=>{$(tool+'-status').textContent=result.tools[tool]?'CLI available':'CLI not found';$(tool+'-status').classList.toggle('ok',Boolean(result.tools[tool]));});['deepseek','groq','soniox'].forEach(provider=>{const value=result.credentials?.[provider];const configured=typeof value==='boolean'?value:Boolean(value?.configured);$(provider+'-status').textContent=configured?'Key available':'No key';$(provider+'-status').classList.toggle('ok',configured);});const storage=result.storage;$('library-folder').value=storage.path;$('storage-details').textContent=`${storage.path} · ${(storage.size_bytes/1024/1024).toFixed(1)} MB`;state.savedSettings=JSON.stringify(settingsPreferences());settingsChanged();return result;}
// Preferences on the Settings page. The save bar shows while they differ from what is saved.
function settingsPreferences(){return{language:$('settings-language').value,knowledge_level:$('settings-level').value,provider:$('settings-provider').value,codex_model:$('codex-model').value.trim(),deepseek_model:$('deepseek-model').value.trim(),output_format:radioValue('settings-output')||'page',slide_theme:radioValue('settings-look')||'forest',transcription_providers:Object.fromEntries([...document.querySelectorAll('[data-workflow]')].map(select=>[select.dataset.workflow,select.value])),groq_model:$('groq-model').value,local_whisper_model:$('local-whisper-model').value,groq_free_only:$('groq-free').checked,allow_paid_llm:$('allow-paid').checked,retain_audio:$('retain-audio').checked};}
function settingsChanged(){$('settings-form').hidden=!state.savedSettings||JSON.stringify(settingsPreferences())===state.savedSettings;}
// The section links follow the section in view; at the end of the page, the last section.
const settingsSections=[...document.querySelectorAll('.settings-section')];
// One card at a time; the save bar sits outside the cards, so a change in a hidden card can still be saved or discarded.
function showSection(part){const current=settingsSections.find(section=>section.id==='settings-'+part)||settingsSections[0];settingsSections.forEach(section=>section.hidden=section!==current);document.querySelectorAll('.settings-nav a').forEach(link=>{const on='settings-'+link.dataset.section===current.id;link.classList.toggle('active',on);if(!on)return link.removeAttribute('aria-current');link.setAttribute('aria-current','page');link.scrollIntoView({block:'nearest',inline:'nearest'});});}
const isDeck=page=>page.metadata?.output_format==='lecture';
function pageCard(page){const deck=isDeck(page);return`<article class="page-card" data-card="${page.id}" data-deck="${deck}"><div class="${coverTint(page.id)}" data-seed="${escapeHTML(page.id)}"><span class="cover-pin">${icon(deck?'slides':'page')}</span><span class="cover-tags"><span class="tag">${deck?'Slides':'Page'}</span><span class="tag">${page.language==='vi'?'Vietnamese':'English'}</span></span></div><div class="card-body"><h2>${escapeHTML(page.title)}</h2><p>${escapeHTML(page.summary)}</p></div><div class="card-footer"><small class="card-meta"><span>${date(page.created_at)}</span><span>${escapeHTML(page.metadata?.provider_name||providerName(page.provider))}</span></small><div class="card-buttons"><button type="button" class="card-delete" data-delete="${page.id}" aria-label="Delete ${escapeHTML(page.title)}" title="Delete">${icon('trash')}</button><button type="button" class="button secondary" data-open="${page.id}" data-deck="${deck}">${deck?'Present':'Explore'}${icon('arrow-right')}</button></div></div></article>`;}
// The start view's trail: the three newest pages, from the whole library whatever the library view is filtered by.
const libraryCount=pages=>{const decks=pages.filter(isDeck).length,count=pages.length-decks;return[count&&`${count} ${count===1?'page':'pages'}`,decks&&`${decks} ${decks===1?'deck':'decks'}`].filter(Boolean).join(' · ');};
function renderRecent(pages){state.recent=pages;$('new-lede').textContent=pages.length?`${libraryCount(pages)} in your library. Choose a format, then add a source.`:'Choose a format, then add a source. Your saved settings apply unless you change them.';const recent=pages.slice(0,3);$('recent').hidden=!recent.length;$('recent-list').innerHTML=recent.map(page=>`<li><button type="button" class="recent-item" data-open="${page.id}" data-deck="${isDeck(page)}"><span class="recent-thumb ${coverTint(page.id)}" data-seed="${escapeHTML(page.id)}">${icon(isDeck(page)?'slides':'page')}</span><span><span class="recent-title">${escapeHTML(page.title)}</span><span class="recent-meta">${isDeck(page)?'Slides':'Page'} · ${date(page.created_at)}</span></span></button></li>`).join('');paintCovers($('recent-list'));}
async function loadRecent(){try{renderRecent((await json('/api/library')).generations);if(state.view==='jobs')renderJob();}catch{}}
async function loadLibrary(){const query=new URLSearchParams({q:$('library-search').value,language:$('library-language').value});const result=await json('/api/library?'+query);state.library=result.generations;if(!$('library-search').value&&!$('library-language').value)renderRecent(result.generations);$('library-total').textContent=result.generations.length?`${libraryCount(result.generations)} saved. `:'';$('library-empty').hidden=result.generations.length>0;$('library-grid').innerHTML=result.generations.map(pageCard).join('');paintCovers($('library-grid'));const filtered=Boolean($('library-search').value||$('library-language').value),empty=$('library-empty'),action=$('library-empty-action');empty.querySelector('h2').textContent=filtered?'No matching pages':'Your next idea starts here';empty.querySelector('p').textContent=filtered?'Try another search or clear the language filter.':'Paste a video link. Get a visual overview, useful connections, and source evidence you can explore.';action.textContent=filtered?'Clear search and filter':'Create your first page';if(filtered)delete action.dataset.view;else action.dataset.view='new';}
function openPage(id,deck){const page=[...state.library,...(state.recent||[])].find(item=>item.id===id);state.readerId=id;state.readerDeck=deck??page?.metadata?.output_format==='lecture';state.readerSlide=1;state.editing=false;$('edit-bar').hidden=true;$('reader-export').hidden=false;$('reader-edit').hidden=!state.readerDeck;$('reader-share').hidden=!state.readerDeck;$('reader-title').textContent=page?.title||'Learning page';$('reader-export').href=`/api/generations/${id}/export`;$('reader-export-label').textContent=state.readerDeck?'Export':'Export HTML';$('reader-frame').src=`/api/generations/${id}/page`;setView('reader');}

async function createPage(regenerate=false){if(state.busy||!state.settings)return;if(state.input==='youtube'){const link=$('video-url'),value=link.value.trim();if(!value||link.validity.typeMismatch){formError(value?'Enter a YouTube watch, short, or shared video link.':'Paste a YouTube link first.');link.setAttribute('aria-invalid','true');link.focus();return;}}state.busy=true;$('create-button').disabled=true;$('create-button').textContent='Saving your request…';formError('');try{let result;if(state.input==='youtube'){result=await json('/api/jobs',{method:'POST',body:JSON.stringify({url:$('video-url').value.trim(),preferences:pagePreferences(),paid_usage_approved:$('new-paid').checked,regenerate})});}else{const file=$('source-file').files[0];if(!file)throw new Error('Choose a source file.');const form=new FormData();form.append('file',file);form.append('title',$('import-title').value.trim());form.append('preference_json',JSON.stringify(pagePreferences()));form.append('paid_usage_approved',String($('new-paid').checked));if(state.input==='audio')form.append('recording_type',state.recording);if(state.input==='transcript'){form.append('url',$('import-url').value.trim());form.append('language',$('source-language').value.trim()||'unknown');}result=await json(state.input==='audio'?'/api/audio-import':'/api/import',{method:'POST',body:form});}if(result.existing?.length){const existing=result.existing[0];const madeAs=values=>(values?.output_format||'page')==='lecture'?'lecture:'+(values?.slide_theme||'forest'):'page';const switching=!result.existing.some(item=>madeAs(item.metadata)===madeAs(pagePreferences()));const otherLook=state.output==='lecture'&&result.existing.some(item=>item.metadata?.output_format==='lecture');$('existing-result').hidden=false;$('existing-result').innerHTML=`<strong>This source is already in your library.</strong><p>${escapeHTML(existing.title)}</p><div class="button-row"><button type="button" class="button secondary" data-open="${existing.id}" data-deck="${existing.metadata?.output_format==='lecture'}">${existing.metadata?.output_format==='lecture'?'Open saved slides':'Open saved page'}</button><button type="button" class="button quiet" id="regenerate-button">${switching?(state.output==='lecture'?(otherLook?'Make slides in this look':'Make lecture slides from it'):'Make an interactive page from it'):'Create a new version'}</button></div>${switching?'<p class="hint">The saved analysis is reused when the language, level, goal, provider and model match.</p>':''}`;if(!state.library.some(page=>page.id===existing.id))state.library.push(existing);}else{state.selectedJob=result.job.id;await refreshJobs();setView('jobs');notice('Your request is saved. Completed work will be kept if processing stops.');}}catch(error){formError(error.message);}finally{state.busy=false;$('create-button').disabled=false;createLabel();}}
function jobTitle(job){const page=[...state.library,...(state.recent||[])].find(item=>item.id===job.generation_id);return job.input.title||page?.title||(job.input.video_id?`YouTube video ${job.input.video_id}`:job.input.url)||'Imported source';}
const jobDot=job=>job.state==='complete'?'done':job.state==='failed'?'error':['awaiting_approval','waiting_for_quota'].includes(job.state)?'wait':active.has(job.state)?'live':'';
async function refreshJobs(){const previous=state.jobs.find(job=>job.id===state.selectedJob);const result=await json('/api/jobs');state.jobs=result.jobs;const count=state.jobs.filter(job=>!terminal.has(job.state)).length;$('job-count').hidden=!count;$('job-count').textContent=count;const finished=state.jobs.filter(job=>job.state==='complete').length;if(state.finished!==undefined&&finished!==state.finished)loadRecent();state.finished=finished;$('jobs-list').innerHTML=state.jobs.length?state.jobs.map(job=>`<button type="button" class="job-item ${job.id===state.selectedJob?'selected':''}" data-job="${job.id}"><span class="job-dot ${jobDot(job)}" aria-hidden="true"></span><span><strong>${escapeHTML(jobTitle(job))}</strong><span class="job-sub">${stageBadge(job)}<small>${date(job.created_at)}</small></span></span></button>`).join(''):'';$('jobs-list').hidden=!state.jobs.length;$('jobs-list').parentElement.classList.toggle('is-empty',!state.jobs.length);if(!state.selectedJob&&state.jobs.length)state.selectedJob=state.jobs[0].id;const current=state.jobs.find(job=>job.id===state.selectedJob);if(current&&state.view==='jobs'&&($('job-detail').dataset.jobId!==current.id||JSON.stringify(previous)!==JSON.stringify(current)))renderJob();else if(!state.jobs.length&&state.view==='jobs'&&$('job-detail').dataset.jobId!=='none')renderJob();}
// The job as a route: five stops on a curved line. Done legs are solid, the leg into the live stop flows in amber, and
// the pill counts the stops left. The stage label and message below say the same in words.
const ROUTE_STOPS=['Captions','Analysis','Checks','Saving','Ready'];
function routeMarkup(job){const stages=['retrieving','analyzing','validating','rendering','complete'];let stage=stages.indexOf(job.state);if(job.state==='transcribing')stage=0;if(job.state==='selecting_visuals')stage=2;const holding=['queued','awaiting_approval'].includes(job.state);if(holding)stage=0;const done=job.state==='complete';
  const xs=[50,150,250,350,450],ys=[44,20,44,20,32];
  const legs=xs.slice(1).map((x,index)=>{const kind=done||index+1<stage?'done':index+1===stage?'live':'next';const mid=(xs[index]+x)/2;return`<path class="leg ${kind}" d="M${xs[index]} ${ys[index]}C${mid} ${ys[index]} ${mid} ${ys[index+1]} ${x} ${ys[index+1]}"/>`;}).join('');
  const stops=ROUTE_STOPS.map((name,index)=>{const kind=done?(index===4?'arrived':'done'):index<stage?'done':index===stage?(holding?'wait':'live'):'';return`<li class="stop ${kind}"><span class="stop-dot">${kind==='done'?icon('check'):kind==='arrived'?icon('flag'):''}</span><span class="stop-name">${name}</span></li>`;}).join('');
  const left=4-stage;const [tone,text]=done?['arrived','Arrived · ready to open']:job.state==='failed'?['stopped','Stopped']:job.state==='cancelled'?['idle','Cancelled']:job.state==='waiting_for_quota'?['idle','Paused · retrying later']:job.state==='awaiting_approval'?['','Waiting for your approval']:job.state==='queued'?['','Starting soon']:['',`${left} ${left===1?'stop':'stops'} left`];
  return`<span class="route-pill ${tone}">${icon('route')}${text}</span><div class="route" aria-hidden="true"><svg class="route-svg" viewBox="0 0 500 64" preserveAspectRatio="none">${legs}</svg><ol class="stops">${stops}</ol></div>`;}
// No jobs: one empty state on the job sheet, an untravelled route, and the way to start one.
const NO_JOBS=`<div class="empty-state"><svg class="empty-route idle" viewBox="0 0 320 90" aria-hidden="true"><path class="route-line" d="M20 64c40 0 40-40 80-40s50 46 100 40 50-36 100-34"/><circle class="route-stop" cx="20" cy="64" r="6"/><circle class="route-stop" cx="160" cy="44" r="6"/><circle class="route-end" cx="300" cy="30" r="9"/></svg><h2>No jobs yet</h2><p>Create a learning page to begin. Its progress shows here, stop by stop.</p><button type="button" class="button primary" data-view="new">Create a learning page</button></div>`;
function renderJob(){const job=state.jobs.find(item=>item.id===state.selectedJob);if(!job){const detail=$('job-detail');detail.dataset.jobId=state.jobs.length?'':'none';detail.innerHTML=state.jobs.length?'<p class="muted">Choose a job to see its progress.</p>':NO_JOBS;return;}const focused=document.activeElement;if(focused&&$('job-detail').contains(focused)&&['INPUT','SELECT','TEXTAREA'].includes(focused.tagName))return;const progress=job.progress||{};const preferences=job.input.preferences;const units=Number.isFinite(progress.total)&&progress.total>0?`<p class="progress-units">${Math.min(progress.completed||0,progress.total)} of ${progress.total} units completed in this stage</p>`:'';let content=`<h2>${escapeHTML(jobTitle(job))}</h2><p class="job-source">${job.input.url?`<span class="job-url">${escapeHTML(job.input.url)}</span><br>`:''}${preferences.output_format==='lecture'?`Lecture slides · ${escapeHTML(lookName(preferences.slide_theme))} · `:''}${job.input.recording_type?escapeHTML(workflowNames[job.input.recording_type])+' · ':''}${preferences.language==='vi'?'Vietnamese':'English'} · ${escapeHTML(providerName(preferences.provider,preferences.api_connections))} · ${escapeHTML(preferences.knowledge_level)}${preferences.learning_goal?`<br>Goal: ${escapeHTML(preferences.learning_goal)}`:''}</p><div class="job-stage">${routeMarkup(job)}<strong>${escapeHTML(labels[job.state]||job.state)}</strong><p>${escapeHTML(progress.message||'Waiting for the worker.')}</p>${units}</div>`;
  if(job.state==='waiting_for_quota'){const when=new Date(job.next_run_at*1000).toLocaleTimeString();content+=`<p class="muted">Next attempt: ${escapeHTML(when)}. Finished sections are saved.</p>`;}
  if(job.error){if(!(job.state==='awaiting_approval'&&job.approval?.reason===job.error.message))content+=job.state==='failed'?`<div class="form-error">${escapeHTML(job.error.message)}</div>`:`<div class="callout"><p>${escapeHTML(job.error.message)}</p></div>`;if(job.error.diagnostics)content+=`<details class="advanced"><summary>Diagnostic details (no key or transcript text)</summary><pre class="diagnostic-log">${escapeHTML(JSON.stringify(job.error.diagnostics,null,2))}</pre></details>`;}
  if(job.state==='awaiting_approval'&&job.approval){const approval=job.approval;const service=transcriptionName(approval.provider);content+=`<section class="job-approval"><h3>${icon('mic')}Approve audio transcription</h3><p>${escapeHTML(approval.reason)}</p><dl>${approval.workflow?`<dt>Source</dt><dd>${escapeHTML(workflowNames[approval.workflow]||approval.workflow)} · set in Settings</dd>`:''}<dt>Provider</dt><dd>${service} · ${escapeHTML(approval.model)}</dd><dt>Speakers</dt><dd>${approval.speaker_labels?'Labelled automatically (Speaker 1, Speaker 2…)':'Not separated'}</dd><dt>Duration</dt><dd>${approval.duration?`${Math.ceil(approval.duration/60)} minutes`:'Not yet known'}</dd><dt>Quota</dt><dd>${escapeHTML(approval.quota||'Remaining quota is unknown.')}</dd><dt>Billing</dt><dd>${approval.local?'Free · runs on this computer':approval.free_only?'Free account only':'Paid route selected'}</dd></dl>${approval.local?`<p>Continuing ${job.input.kind==='audio_import'?'transcribes this saved audio':'downloads this video’s audio and transcribes it'} on this computer. Nothing is uploaded. The transcript keeps source timing.</p><label class="check"><input id="audio-consent" type="checkbox">I approve transcribing this source with Local Whisper.</label><button type="button" id="approve-audio" class="button primary">Transcribe on this computer</button></section>`:`<p>Continuing ${job.input.kind==='audio_import'?'uploads this saved audio':'downloads this video’s audio and uploads it'} to ${service}. The transcript keeps source timing.</p><label class="check"><input id="audio-consent" type="checkbox">I approve audio processing for this source and ${service} model.</label>${approval.free_only?`<label class="check"><input id="free-confirm" type="checkbox">I checked ${service}: this key uses a Free account with no paid billing.</label>`:`<label class="check"><input id="paid-audio-confirm" type="checkbox">I approve paid ${service} transcription for this source.</label>`}<button type="button" id="approve-audio" class="button primary">Continue with ${service}</button><p class="hint">The app cannot read or enforce your ${service} billing plan. Confirm it in your account before continuing.</p></section>`}`;if(approval.languages?.length){content+=`<form id="language-retry" class="callout"><label for="retry-source-language">Available caption languages</label><select id="retry-source-language">${approval.languages.map(lang=>`<option value="${escapeHTML(lang.code)}">${escapeHTML(lang.name||lang.code)}${lang.generated?' · auto-generated':''}</option>`).join('')}</select><button class="button secondary" type="submit">Retry these captions</button></form>`;}}
  if(job.state==='complete'){
    content+=`<div class="button-row"><button type="button" class="button primary" data-open="${job.generation_id}" data-deck="${preferences.output_format==='lecture'}">${preferences.output_format==='lecture'?'Present lecture slides':'Explore learning page'}${icon('arrow-right')}</button><a class="button secondary" href="/api/generations/${job.generation_id}/export">${icon('download')}Export HTML</a></div>`;
    const info=state.generationInfo[job.generation_id];
    if(info&&info!=='loading')content+=`<details class="advanced"><summary>Generation details</summary><p class="hint">Provider: ${escapeHTML(info.provider_name||providerName(info.provider,preferences.api_connections))} · model: ${escapeHTML(info.model)}<br>Recorded input tokens: ${info.input_tokens===null?'Unavailable':escapeHTML(info.input_tokens)} · output tokens: ${info.output_tokens===null?'Unavailable':escapeHTML(info.output_tokens)}<br>${escapeHTML(info.usage_scope)}<br>Subscription allowance: unknown. Billed cost: unavailable.</p></details>`;
    else if(!info){state.generationInfo[job.generation_id]='loading';json(`/api/generations/${job.generation_id}/details`).then(value=>{state.generationInfo[job.generation_id]=value;if(state.selectedJob===job.id)renderJob();}).catch(()=>{state.generationInfo[job.generation_id]={provider:preferences.provider,model:preferences.model||'Provider default',input_tokens:null,output_tokens:null,usage_scope:'Usage records are unavailable.'};});}
  }
  else if(['failed','cancelled','waiting_for_quota'].includes(job.state))content+=`<form id="retry-form"><label for="retry-provider">Retry with AI provider</label><select id="retry-provider">${providerOptions(preferences.provider)}</select><label class="check"><input id="retry-paid" type="checkbox">I approve API requests for this retry. Hosted providers may charge.</label><button class="button primary" type="submit">Retry saved work</button></form>`;
  if(job.state!=='complete'&&job.state!=='cancelled')content+=`<div class="button-row section-gap"><button type="button" class="button quiet" data-cancel="${job.id}">${icon('close')}Cancel processing</button></div>`;
  if(['failed','cancelled','awaiting_approval','waiting_for_quota'].includes(job.state))content+=`<details class="recovery"><summary>Import a replacement transcript</summary><form id="recover-form"><label for="recover-file">TXT, SRT, VTT, or JSON</label><input id="recover-file" type="file" accept=".txt,.srt,.vtt,.json" required><button class="button secondary" type="submit">Use this transcript</button></form><button type="button" id="delete-audio" class="button quiet">Delete temporary audio</button></details>`;
  // Keep selected checkbox values through polling, while stage updates remain visible.
  const detail=$('job-detail');
  const sameJob=detail.dataset.jobId===job.id;
  const checked=sameJob?[...detail.querySelectorAll('input[type=checkbox]:checked')].map(input=>input.id):[];
  const expanded=sameJob?new Set([...detail.querySelectorAll('details[open] summary')].map(summary=>summary.textContent)):new Set();
  detail.innerHTML=content;detail.dataset.jobId=job.id;
  checked.forEach(id=>{if($(id))$(id).checked=true;});
  detail.querySelectorAll('details summary').forEach(summary=>{if(expanded.has(summary.textContent))summary.parentElement.open=true;});
}
async function jobAction(path,body){try{const result=await json(`/api/jobs/${state.selectedJob}/${path}`,{method:'POST',body:JSON.stringify(body||{})});state.selectedJob=result.id;await refreshJobs();renderJob();}catch(error){notice(error.message,true);}}
