async function downloadBackup(){const button=$('backup-button');button.disabled=true;try{const response=await api('/api/backup',{method:'POST'});const blob=await response.blob();const link=document.createElement('a');const url=URL.createObjectURL(blob);link.href=url;link.download=(response.headers.get('content-disposition')?.match(/filename="?([^";]+)/)?.[1])||'distill-backup.zip';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Backup downloaded. API keys are excluded.');}catch(error){notice(error.message,true);}finally{button.disabled=false;}}

document.addEventListener('click',async event=>{const button=event.target.closest('button,a');if(!button){const card=event.target.closest('[data-card]');if(card&&!String(getSelection()))openPage(card.dataset.card,card.dataset.deck==='true');return;}try{if(button.id==='add-connection'||button.id==='cancel-connection'||button.dataset.editConnection||button.dataset.defaultConnection||button.dataset.deleteConnection){await connectionAction(button);}else if(button.dataset.view){event.preventDefault();setView(button.dataset.view);}else if(button.id==='reader-export'&&state.readerDeck){event.preventDefault();openExportDialog();}else if(button.dataset.input)inputMode(button.dataset.input);else if(button.dataset.output)outputMode(button.dataset.output);else if(button.dataset.look)lookMode(button.dataset.look);else if(button.dataset.recording)recordingMode(button.dataset.recording);else if(button.dataset.open)openPage(button.dataset.open,button.dataset.deck==='true');else if(button.dataset.job){state.selectedJob=button.dataset.job;renderJob();document.querySelectorAll('[data-job]').forEach(item=>item.classList.toggle('selected',item.dataset.job===state.selectedJob));if(matchMedia('(max-width:899px)').matches)$('job-detail').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});}else if(button.dataset.cancel){state.selectedJob=button.dataset.cancel;await jobAction('cancel');}else if(button.dataset.delete){if(confirm('Delete this saved version and its source files? Other versions stay in your library.')){await json('/api/generations/'+button.dataset.delete,{method:'DELETE'});await loadLibrary();await refreshJobs();notice('Saved version deleted.');}}else if(button.id==='regenerate-button')await createPage(true);else if(button.id==='approve-audio'){if(!$('audio-consent').checked)throw new Error('Approve audio processing for this source before continuing.');await jobAction('approve',{approved:true,free_account_confirmed:Boolean($('free-confirm')?.checked),paid_usage_approved:Boolean($('paid-audio-confirm')?.checked)});}else if(button.id==='delete-audio'){await json(`/api/jobs/${state.selectedJob}/audio`,{method:'DELETE'});notice('Temporary audio deleted. Saved text and pages are kept.');}else if(button.dataset.removeKey){await json('/api/credentials/'+button.dataset.removeKey,{method:'DELETE'});await loadSettings(false);notice('Saved key removed. Environment keys, if present, must be removed outside the app.');}}catch(error){notice(error.message,true);}});
document.addEventListener('submit',async event=>{const form=event.target;event.preventDefault();try{if(form.id==='new-form')await createPage();else if(form.id==='retry-form')await jobAction('retry',{provider:$('retry-provider').value,paid_usage_approved:$('retry-paid').checked});else if(form.id==='language-retry')await jobAction('retry',{source_language:$('retry-source-language').value});else if(form.id==='recover-form'){const body=new FormData();body.append('file',$('recover-file').files[0]);await json(`/api/jobs/${state.selectedJob}/import`,{method:'POST',body});await refreshJobs();renderJob();}else if(form.id==='library-folder-form'){const button=$('library-folder-button');button.disabled=true;try{const result=await json('/api/library/location',{method:'PUT',body:JSON.stringify({path:$('library-folder').value.trim()})});await loadSettings(false);await loadLibrary();notice(result.message);}finally{button.disabled=false;}}else if(form.id==='export-form')await runExport();else if(form.id==='connection-editor')await saveConnection();else if(form.id==='settings-form'){await json('/api/settings',{method:'PUT',body:JSON.stringify(settingsPreferences())});await loadSettings();notice('Preferences saved. New pages will use these defaults.');}else if(form.classList.contains('credential-form')){const provider=form.dataset.provider;const input=$(provider+'-key');if(!input.value.trim())throw new Error('Enter an API key first.');await json('/api/credentials/'+provider,{method:'PUT',body:JSON.stringify({key:input.value.trim()})});input.value='';await loadSettings(false);notice('API key saved in the operating system credential store.');}}catch(error){notice(error.message,true);}});
