// Presented slides: the sandboxed reader frame cannot take full screen itself, so the workspace puts the frame in full screen.
// A deck takes keyboard focus when it opens, so arrows, N and F work at once.
function toggleReaderFullscreen(){if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});else $('reader-frame').requestFullscreen?.().catch(()=>{});}
// The deck says which slide is in view, and in edit mode what has changed; the frame cannot reach the app itself.
addEventListener('message',event=>{if(event.source!==$('reader-frame').contentWindow)return;const data=event.data||{};
  if(data.type==='distill-fullscreen')toggleReaderFullscreen();
  if(data.type==='distill-slide'&&Number.isInteger(data.slide)&&!state.editing)state.readerSlide=data.slide;
  if(data.type==='distill-edit'&&state.editing&&Array.isArray(data.changes)&&Array.isArray(data.problems)){state.edit={version:String(data.version||''),changes:data.changes,problems:data.problems,slide:Number(data.slide)||1};state.readerSlide=state.edit.slide;editStatus();}
  if(data.type==='distill-structure'&&state.editing&&data.op)structureOp(data.op);
  if(data.type==='distill-layout'&&state.editing&&Array.isArray(data.slide))openLayoutDialog(data.slide);});
document.addEventListener('keydown',event=>{if(event.key.toLowerCase()!=='f'||event.ctrlKey||event.metaKey||event.altKey||!state.readerDeck||$('view-reader').hidden||event.target.closest?.('input, textarea, select'))return;event.preventDefault();toggleReaderFullscreen();});
