// Share to a phone: the app renders a phone copy, then shows its tailnet link as a QR code, or how to set Tailscale up.
async function shareToPhone(){const button=$('reader-share');button.disabled=true;try{const share=await json(`/api/generations/${state.readerId}/share`,{method:'POST'});const tailnet=share.tailscale;$('share-ready').hidden=!share.url;$('share-setup').hidden=!!share.url;$('share-download').href=share.download;
  if(share.url){$('share-qr').src=share.qr;$('share-url').href=share.url;$('share-url').textContent=share.url;}
  else{$('share-setup-text').textContent=!tailnet.installed?'Tailscale is not installed on this computer. Install it and sign in, or download the phone HTML.':!tailnet.connected?'Tailscale is not connected. Open Tailscale and sign in, then share again.':'Tailscale does not reach this app yet. Run this once on this computer, then share again:';$('share-command').textContent=tailnet.command;$('share-command').parentElement.hidden=!tailnet.installed||!tailnet.connected;}
  $('share-dialog').showModal();}catch(error){notice(error.message,true);}finally{button.disabled=false;}}
