// Edit slides: the frame shows the deck drawn from its saved records with its text editable in place, at the slide in
// view, and reports each change. Save sends the changes; the deck is drawn again with them and opens at the same slide.
function setEditing(on,slide=state.readerSlide||1){state.editing=on;state.edit={version:'',changes:[],problems:[],slide};$('edit-bar').hidden=!on;['reader-edit','reader-share'].forEach(id=>$(id).hidden=on||!state.readerDeck);$('reader-export').hidden=on;$('reader-frame').src=`/api/generations/${state.readerId}/${on?'slides/edit':'page'}#slide-${slide}`;editStatus();}
function editStatus(){const edit=state.edit||{changes:[],problems:[]};const problem=edit.problems[0];const count=edit.changes.length;
  $('edit-status').textContent=problem?`Slide ${problem.slide}: ${problem.problem==='empty'?'a text is empty. Type it, or press Esc in it to put it back.':`a text is too long, ${problem.length} of ${problem.limit} characters.`}`:count?`${count} ${count===1?'change':'changes'} not saved yet.`:'Click a text on a slide to change it. Presenter notes are under each slide.';
  $('edit-status').classList.toggle('error',Boolean(problem));$('edit-save').disabled=!count||Boolean(problem)||Boolean(state.saving);}
function leaveEdit(){if(!state.editing)return true;if(state.edit.changes.length&&!confirm('Discard your changes to these slides?')){history.replaceState(null,'','#reader');return false;}setEditing(false,state.edit.slide);return true;}
async function saveEdits(){const edit=state.edit;if(!edit.changes.length||edit.problems.length)return;state.saving=true;editStatus();
  try{await json(`/api/generations/${state.readerId}/slides`,{method:'PUT',body:JSON.stringify({version:edit.version,changes:edit.changes})});setEditing(false,edit.slide);notice('Slide text saved.');}
  catch(error){notice(error.message,true);}finally{state.saving=false;editStatus();}}
