function ytdlpText(s){if(!s.installed)return'yt-dlp is not installed. Update installs it.';let text=`yt-dlp ${s.installed}`;if(s.latest_error)text+=` · ${s.latest_error}`;else if(s.latest)text+=s.update_available?` · ${s.latest} is available`:' · up to date';return text+(s.javascript_runtime?` · JavaScript challenges: ${s.javascript_runtime==='deno'?'Deno':'Node.js'}`:' · No Deno or Node.js found: some videos may not download');}
async function ytdlpStatus(check=false){try{const s=await json(`/api/tools/yt-dlp${check?'?check=true':''}`);$('ytdlp-status').textContent=ytdlpText(s);$('ytdlp-update').hidden=!(s.update_available||!s.installed);}catch(error){$('ytdlp-status').textContent=error.message;}}
$('ytdlp-check').addEventListener('click',async()=>{const button=$('ytdlp-check');button.disabled=true;$('ytdlp-status').textContent='Checking the newest yt-dlp release…';await ytdlpStatus(true);button.disabled=false;});
$('ytdlp-update').addEventListener('click',async()=>{const button=$('ytdlp-update');button.disabled=true;button.textContent='Updating…';$('ytdlp-status').textContent='Installing the newest yt-dlp. This can take a minute.';try{const result=await json('/api/tools/yt-dlp/update',{method:'POST'});notice(result.previous===result.installed?`yt-dlp ${result.installed} is already the newest release.`:`yt-dlp updated to ${result.installed}.`);await ytdlpStatus(true);}catch(error){notice(error.message,true);await ytdlpStatus();}finally{button.disabled=false;button.textContent='Update yt-dlp';}});
