// Structure edits (hide, show, delete, duplicate, move, add, layout, undo, redo). One request carries the edit with the text
// changes not saved yet, so a step is never half made; the deck then loads again in edit mode at the slide the server names
// (#at-P.S), or at the same slide after undo and redo. The frame is sandboxed, so it only asks; this page makes the request.
const structureNotes={hide:'Slide hidden. Show brings it back.',show:'Slide shown again.',delete:'Slide deleted. Undo brings it back.',duplicate:'Slide duplicated.',move:'Slide moved.',add:'Blank slide added. Click its text to write it.',layout:'Layout changed.',undo:'Undone.',redo:'Redone.'};
function editReload(at){const slide=state.edit.slide;state.edit={version:'',changes:[],problems:[],slide};$('reader-frame').src=`/api/generations/${state.readerId}/slides/edit?r=${Date.now()}#${at?`at-${at}`:`slide-${slide}`}`;editStatus();}
async function structureOp(op){
  const edit=state.edit;if(state.structuring)return;
  if(!edit.version){notice('The slides are still opening. Try again in a moment.',true);return;}
  const undoing=op.type==='undo'||op.type==='redo',dropped=undoing?edit.changes.length:0;
  if(dropped&&!confirm(`${op.type==='undo'?'Undo':'Redo'} drops the ${dropped} text ${dropped===1?'change':'changes'} you have not saved. Continue?`))return;
  state.structuring=true;
  try{const result=await json(`/api/generations/${state.readerId}/slides/structure`,{method:'POST',body:JSON.stringify({version:edit.version,changes:undoing?[]:edit.changes,op})});
    editReload(result.at);notice([structureNotes[op.type],...result.warnings].join(' '));}
  catch(error){notice(error.message,true);}finally{state.structuring=false;}
}
// Change layout: every layout with whether this slide fits it and why not, and a preview of the slide in the chosen one.
const layoutState={slide:'',options:[],choice:''};
async function openLayoutDialog(slide){
  layoutState.slide=slide.join('.');layoutState.choice='';layoutState.options=[];
  $('layout-apply').disabled=true;$('layout-frame').removeAttribute('src');$('layout-empty').hidden=false;$('layout-warnings').innerHTML='';
  $('layout-options').innerHTML='<li class="muted">Checking which layouts fit…</li>';$('layout-dialog').showModal();
  try{const result=await json(`/api/generations/${state.readerId}/slides/layout-options?slide=${layoutState.slide}`);layoutState.options=result.options;
    $('layout-options').innerHTML=result.options.map(option=>`<li><button type="button" class="layout-option" data-layout="${escapeHTML(option.layout)}" aria-pressed="false"${option.available?'':' disabled'}><strong>${escapeHTML(option.name)}${option.current?' · current':''}</strong><span>${escapeHTML(option.available||option.current?option.hint:option.reason)}</span></button></li>`).join('');}
  catch(error){$('layout-dialog').close();notice(error.message,true);}
}
function chooseLayout(layout){
  const option=layoutState.options.find(item=>item.layout===layout);if(!option?.available)return;layoutState.choice=layout;
  document.querySelectorAll('.layout-option').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.layout===layout)));
  $('layout-warnings').innerHTML=option.warnings.map(text=>`<li>${escapeHTML(text)}</li>`).join('');
  $('layout-empty').hidden=true;fitLayoutPreview();$('layout-frame').src=`/api/generations/${state.readerId}/slides/layout-preview?slide=${layoutState.slide}&layout=${layout}`;$('layout-apply').disabled=false;
}
// The preview is the slide at its own 1280 x 720 size, scaled to the room the dialog gives it (the CSP forbids style attributes, so the CSSOM sets it).
function fitLayoutPreview(){const box=$('layout-frame').parentElement;box.style.setProperty('--preview-scale',(box.clientWidth/1280).toFixed(4));}
addEventListener('resize',()=>{if($('layout-dialog').open)fitLayoutPreview();});
$('layout-options').addEventListener('click',event=>{const button=event.target.closest('.layout-option');if(button)chooseLayout(button.dataset.layout);});
$('layout-cancel').addEventListener('click',()=>$('layout-dialog').close());
$('layout-apply').addEventListener('click',()=>{if(!layoutState.choice)return;$('layout-dialog').close();structureOp({type:'layout',slide:layoutState.slide.split('.').map(Number),layout:layoutState.choice});});
// Export: HTML is the saved file; PDF and PNG are drawn on this computer by Edge or Chrome, which can take a few seconds a slide.
function exportOptions(){const format=radioValue('export-format');$('export-which').hidden=format==='html';$('export-scale-group').hidden=format!=='png';$('export-theme-group').hidden=format==='html';$('export-go').lastChild.textContent=format==='html'?'Download':'Download '+format.toUpperCase();}
function openExportDialog(){$('export-current').textContent=`This slide (${state.readerSlide||1})`;$('export-status').textContent='';$('export-status').classList.remove('error');exportOptions();$('export-dialog').showModal();}
async function runExport(){
  const format=radioValue('export-format'),button=$('export-go'),status=$('export-status');
  if(format==='html'){const link=document.createElement('a');link.href=`/api/generations/${state.readerId}/export`;document.body.append(link);link.click();link.remove();$('export-dialog').close();return;}
  const query=new URLSearchParams({format,slide:radioValue('export-slide')==='all'?'all':String(state.readerSlide||1),theme:radioValue('export-theme')||'light'});if(format==='png')query.set('scale',radioValue('export-scale')||'1');
  button.disabled=true;status.classList.remove('error');status.textContent=radioValue('export-slide')==='all'?'Drawing every slide. This can take several seconds…':'Drawing the slide…';
  try{const response=await api(`/api/generations/${state.readerId}/slides/export?${query}`);saveBlob(await response.blob(),response,`slides.${format}`);$('export-dialog').close();notice(format==='pdf'?'PDF saved.':'Pictures saved.');}
  catch(error){status.textContent=error.message;status.classList.add('error');}finally{button.disabled=false;}
}
document.querySelectorAll('#export-form input[type=radio]').forEach(input=>input.addEventListener('change',exportOptions));
$('export-cancel').addEventListener('click',()=>$('export-dialog').close());
